
document.addEventListener("DOMContentLoaded", () => {
 const body=document.body;
 const KEY="taskflow.userTasks", DONE="taskflow.completed";
 const read=(key,fallback)=>{try{const x=JSON.parse(localStorage.getItem(key));return x ?? fallback}catch{return fallback}};
 const tasks=()=>read(KEY,[]);
 const saveTasks=x=>localStorage.setItem(KEY,JSON.stringify(x));
 const completed=()=>read(DONE,{});
 const saveCompleted=x=>localStorage.setItem(DONE,JSON.stringify(x));
 const pad=n=>String(n).padStart(2,"0");
 const iso=d=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
 const todayISO=iso(new Date());
 const dateLabel=s=>{if(!s)return "";const d=new Date(s+"T00:00:00");if(s===todayISO)return "Сегодня";const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);if(s===iso(tomorrow))return "Завтра";return d.toLocaleDateString("ru-RU",{day:"numeric",month:"long"});};
 const periodFor=s=>{const d=new Date(s+"T00:00:00"),n=new Date();n.setHours(0,0,0,0);const diff=Math.floor((d-n)/86400000);if(diff<=0)return"today";if(diff<=7)return"week";return"month"};
 const cat={work:"Работа",study:"Учёба",personal:"Личное",health:"Здоровье"};
 const color={work:"",study:"purple",personal:"green",health:"green"};

 // Navigation drawer
 const menu=document.querySelector(".mobile-menu"), sidebar=document.querySelector(".sidebar");
 if(menu&&sidebar){
  const overlay=document.createElement("div");overlay.className="nav-overlay";document.body.appendChild(overlay);
  const close=()=>{sidebar.classList.remove("drawer-open");overlay.classList.remove("open");body.classList.remove("drawer-active");menu.setAttribute("aria-expanded","false")};
  const toggle=()=>{const open=!sidebar.classList.contains("drawer-open");sidebar.classList.toggle("drawer-open",open);overlay.classList.toggle("open",open);body.classList.toggle("drawer-active",open);menu.setAttribute("aria-expanded",String(open))};
  menu.addEventListener("click",toggle);overlay.addEventListener("click",close);
  sidebar.querySelectorAll("a").forEach(a=>a.addEventListener("click",close));
  document.addEventListener("keydown",e=>{if(e.key==="Escape")close()});
 }
 document.querySelectorAll("[data-nav]").forEach(a=>a.classList.toggle("active",a.dataset.nav===body.dataset.page));

 if(body.dataset.page==="tasks"){
  const list=document.getElementById("taskList"), empty=document.getElementById("emptyTasks"), search=document.getElementById("taskSearch");
  const filters=[...document.querySelectorAll(".filter")]; let current="all";
  function bind(row){
   const check=row.querySelector(".check"); if(!check)return;
   check.addEventListener("click",()=>{
    const on=!check.classList.contains("checked");check.classList.toggle("checked",on);row.classList.toggle("done",on);check.setAttribute("aria-pressed",String(on));
    const m=completed();m[row.dataset.id]=on;saveCompleted(m);
   });
  }
  function make(t){
   const row=document.createElement("article");row.className="task-row";row.dataset.id=t.id;row.dataset.period=periodFor(t.date);row.dataset.title=(t.title||"").toLowerCase();
   const check=document.createElement("button");check.className="check";check.type="button";check.setAttribute("aria-label","Отметить задачу");check.setAttribute("aria-pressed","false");
   const info=document.createElement("div");info.className="task-info";const strong=document.createElement("strong");strong.textContent=t.title||"Без названия";const meta=document.createElement("span");meta.textContent=[dateLabel(t.date),t.time].filter(Boolean).join(", ");info.append(strong,meta);
   const tag=document.createElement("span");tag.className=`tag ${t.category||"work"}`;tag.textContent=cat[t.category]||"Работа";row.append(check,info,tag);
   const done=Boolean(completed()[t.id]||t.completed);if(done){check.classList.add("checked");row.classList.add("done");check.setAttribute("aria-pressed","true")}bind(row);return row;
  }
  function render(){
   list.querySelectorAll(".task-row").forEach(x=>x.remove());
   const all=tasks();all.forEach(t=>list.insertBefore(make(t),empty));
   const q=(search.value||"").trim().toLowerCase();let count=0;
   list.querySelectorAll(".task-row").forEach(r=>{const show=(current==="all"||r.dataset.period===current)&&(!q||r.dataset.title.includes(q));r.hidden=!show;if(show)count++});
   empty.style.display=count?"none":"block";
  }
  filters.forEach(f=>f.addEventListener("click",()=>{filters.forEach(x=>x.classList.remove("active"));f.classList.add("active");current=f.dataset.filter;render()}));
  search.addEventListener("input",render);render();
 }

 if(body.dataset.page==="add-task"){
  const date=document.getElementById("date"); if(date)date.value=todayISO;
  document.querySelectorAll(".priority button").forEach(b=>b.addEventListener("click",()=>{
   document.querySelectorAll(".priority button").forEach(x=>x.classList.remove("selected"));b.classList.add("selected");document.getElementById("priority").value=b.textContent.trim();
  }));
  document.getElementById("screenTaskForm")?.addEventListener("submit",e=>{
   e.preventDefault();const data=Object.fromEntries(new FormData(e.target).entries());
   const t={id:"task-"+Date.now(),title:data.title.trim(),date:data.date,time:data.time,category:data.category||"work",priority:data.priority||"Средний",description:data.description||"",reminder:data.reminder||"30"};
   if(!t.title||!t.date){e.target.reportValidity();return}const all=tasks();all.unshift(t);saveTasks(all);location.href="index.html";
  });
 }

 if(body.dataset.page==="calendar"){
  const grid=document.getElementById("calendarGrid"),title=document.getElementById("monthTitle"),todayBox=document.getElementById("todayTasks");
  const names=["Январь","Февраль","Март","Апрель","Май","Июнь","Июль","Август","Сентябрь","Октябрь","Ноябрь","Декабрь"];
  let view=new Date();view.setDate(1);
  function draw(){
   const y=view.getFullYear(),m=view.getMonth();title.textContent=`${names[m]} ${y}`;
   const first=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate(),prev=new Date(y,m,0).getDate();grid.innerHTML="";
   const all=tasks();
   for(let i=0;i<42;i++){
    const n=i-first+1,c=document.createElement("div");c.className="day";const num=document.createElement("span");num.className="num";
    if(n<1){c.classList.add("other");num.textContent=prev+n}
    else if(n>days){c.classList.add("other");num.textContent=n-days}
    else{
     num.textContent=n;const ds=`${y}-${pad(m+1)}-${pad(n)}`;if(ds===todayISO)c.classList.add("today");
     all.filter(t=>t.date===ds).slice(0,2).forEach(t=>{const e=document.createElement("span");e.className=`day-event ${color[t.category]||""}`;e.textContent=t.title;c.append(e)});
    }c.prepend(num);grid.append(c);
   }
   todayBox.innerHTML="";const todays=all.filter(t=>t.date===todayISO);
   if(!todays.length){todayBox.innerHTML='<div class="empty-state" style="display:block">На сегодня задач нет</div>';return}
   todays.forEach(t=>{const r=document.createElement("article");r.className="planned-task";r.innerHTML=`<span class="dot ${t.category==="personal"?"green":"blue"}"></span><div><strong></strong><span>${t.time?`Сегодня, ${t.time}`:"Сегодня"}</span></div><span class="tag ${t.category||"work"}">${cat[t.category]||"Работа"}</span>`;r.querySelector("strong").textContent=t.title;todayBox.append(r)});
  }
  document.querySelector("[data-calendar-prev]")?.addEventListener("click",()=>{view.setMonth(view.getMonth()-1);draw()});
  document.querySelector("[data-calendar-next]")?.addEventListener("click",()=>{view.setMonth(view.getMonth()+1);draw()});
  draw();
 }
});
